class Solution {
public:
    int centeredSubarrays(vector<int>& nums) {
        int n = nums.size(), ans = 0;
        for (int l = 0; l < n; ++l) {
            unordered_set<long long> seen;
            long long sum = 0;
            for (int r = l; r < n; ++r) {
                sum += nums[r];
                seen.insert(nums[r]);
                if (seen.count(sum)) ++ans;
            }
        }
        return ans;
    }
};
